#include <vector>
#include <algorithm>
using namespace std;

struct Node {
    Node* child[2] = {nullptr, nullptr};
};

class Solution {
    Node* root = new Node();

    void insert(int val) {
        Node* curr = root;
        for (int i = 30; i >= 0; --i) {
            int b = (val >> i) & 1;
            if (!curr->child[b]) curr->child[b] = new Node();
            curr = curr->child[b];
        }
    }

    int queryMax(int val) {
        if (!root->child[0] && !root->child[1]) return -1;
        Node* curr = root;
        int res = 0;
        for (int i = 30; i >= 0; --i) {
            int b = (val >> i) & 1;
            int opp = 1 - b;
            if (curr->child[opp]) {
                res |= (1 << i);
                curr = curr->child[opp];
            } else {
                curr = curr->child[b];
            }
        }
        return res;
    }

public:
    vector<int> maximizeXor(vector<int>& nums, vector<vector<int>>& queries) {
        sort(nums.begin(), nums.end());
        int q = queries.size();
        vector<int> order(q);
        for (int i = 0; i < q; ++i) order[i] = i;
        sort(order.begin(), order.end(), [&](int a, int b) {
            return queries[a][1] < queries[b][1];
        });
        vector<int> ans(q);
        int idx = 0;
        int n = nums.size();
        for (int i : order) {
            int x = queries[i][0];
            int m = queries[i][1];
            while (idx < n && nums[idx] <= m) {
                insert(nums[idx]);
                idx++;
            }
            ans[i] = queryMax(x);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    static class Node {
        Node[] child = new Node[2];
    }

    private Node root = new Node();

    private void insert(int val) {
        Node curr = root;
        for (int i = 30; i >= 0; --i) {
            int b = (val >> i) & 1;
            if (curr.child[b] == null) curr.child[b] = new Node();
            curr = curr.child[b];
        }
    }

    private int queryMax(int val) {
        if (root.child[0] == null && root.child[1] == null) return -1;
        Node curr = root;
        int res = 0;
        for (int i = 30; i >= 0; --i) {
            int b = (val >> i) & 1;
            int opp = 1 - b;
            if (curr.child[opp] != null) {
                res |= (1 << i);
                curr = curr.child[opp];
            } else {
                curr = curr.child[b];
            }
        }
        return res;
    }

    public int[] maximizeXor(int[] nums, int[][] queries) {
        Arrays.sort(nums);
        int q = queries.length;
        Integer[] order = new Integer[q];
        for (int i = 0; i < q; ++i) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(queries[a][1], queries[b][1]));
        int[] ans = new int[q];
        int idx = 0;
        int n = nums.length;
        for (int i : order) {
            int x = queries[i][0];
            int m = queries[i][1];
            while (idx < n && nums[idx] <= m) {
                insert(nums[idx]);
                idx++;
            }
            ans[i] = queryMax(x);
        }
        return ans;
    }
}

