var maximizeXor = function(nums, queries) {
    nums.sort((a, b) => a - b);
    const q = queries.length;
    const order = Array.from({ length: q }, (_, i) => i);
    order.sort((a, b) => queries[a][1] - queries[b][1]);

    const root = [null, null];
    const insert = (val) => {
        let curr = root;
        for (let i = 30; i >= 0; --i) {
            const b = (val >> i) & 1;
            if (!curr[b]) curr[b] = [null, null];
            curr = curr[b];
        }
    };

    const queryMax = (val) => {
        if (!root[0] && !root[1]) return -1;
        let curr = root;
        let res = 0;
        for (let i = 30; i >= 0; --i) {
            const b = (val >> i) & 1;
            const opp = 1 - b;
            if (curr[opp]) {
                res |= (1 << i);
                curr = curr[opp];
            } else {
                curr = curr[b];
            }
        }
        return res;
    };

    const ans = Array(q);
    let idx = 0;
    const n = nums.length;
    for (const i of order) {
        const [x, m] = queries[i];
        while (idx < n && nums[idx] <= m) {
            insert(nums[idx]);
            idx++;
        }
        ans[i] = queryMax(x);
    }
    return ans;
};
